function pinXY(lat,lng,allLocs){if(!allLocs||allLocs.length<2)return{x:50,y:50};const lats=allLocs.map(l=>l.lat),lngs=allLocs.map(l=>l.lng),minLat=Math.min(...lats)-0.05,maxLat=Math.max(...lats)+0.05,minLng=Math.min(...lngs)-0.05,maxLng=Math.max(...lngs)+0.05,latRange=maxLat-minLat||0.1,lngRange=maxLng-minLng||0.1;return{x:Math.max(5,Math.min(92,((lng-minLng)/lngRange)*82+5)),y:Math.max(8,Math.min(90,((maxLat-lat)/latRange)*74+8))}}
function renderMap(rows){let gps=rows.filter(d=>d.location),map=document.getElementById('map');document.getElementById('gpsDrivers').textContent=gps.length;document.getElementById('milesTracked').textContent=rows.reduce((a,d)=>a+d.distanceMiles,0).toFixed(2);document.getElementById('maxEscalation').textContent=rows.reduce((a,d)=>Math.max(a,d.escalationLevel),0);if(fleetMode){document.getElementById('gpsCount').textContent='excluded from protected view';map.innerHTML='<div><strong>GPS is not included</strong><p class="sub">The protected fleet summary excludes driver coordinates by design.</p></div>';return}document.getElementById('gpsCount').textContent=gps.length?gps.length+' local GPS active':'waiting for local GPS';if(!gps.length){map.innerHTML='<div><strong>No local GPS data</strong><p class="sub">Same-browser drivers must opt in before location appears.</p></div>';return}map.innerHTML='<div style="position:absolute;left:16px;top:14px;text-align:left"><strong>Same-browser GPS locations</strong><p class="sub">Opt-in local session or demo pins.</p></div>'+gps.map(d=>{let p=pinXY(d.location.lat,d.location.lng,gps.map(g=>g.location)),c=d.stale?'stale':cls(d.status),score=d.hasSafetyScore?d.safetyScore:'--';return `<div class="pin ${c}" style="left:${p.x}%;top:${p.y}%"><div class="tip"><strong>${esc(d.name)}</strong><br>${esc(d.status)} · score ${esc(score)}<br><span class="coords">${d.location.lat.toFixed(4)}, ${d.location.lng.toFixed(4)}</span><br>${d.speedMph} mph · ${d.distanceMiles.toFixed(2)} mi</div></div>`}).join('')}
function filterRows(rows){let f=document.getElementById('riskFilter')?.value||'all',q=(document.getElementById('driverSearch')?.value||'').trim().toLowerCase();return rows.filter(d=>(f==='all'||(f==='danger'&&cls(d.status)==='danger')||(f==='watch'&&cls(d.status)==='watch')||(f==='stale'&&d.active!==false&&d.hasSession&&d.stale)||(f==='gps'&&!fleetMode&&d.location)||(f==='nogps'&&!fleetMode&&d.active!==false&&!d.location))&&(!q||[d.name,d.route,d.status,d.driverId].join(' ').toLowerCase().includes(q)))}
