function durationLabel(start,end){let a=safeDate(start),b=safeDate(end);if(!a||!b||b<a||b.getTime()>Date.now())return'Not recorded';let minutes=Math.round((b-a)/60000);return minutes<60?minutes+' min':Math.floor(minutes/60)+'h '+(minutes%60)+'m'}
