function requestDashboardCSVDownload(csv,filename,protectedOnly=false){
  const owner=currentProtectedOwner(),generation=protectedFleetGeneration,mode=fleetMode;
  if(protectedOnly?!allowProtectedShare():!allowDashboardShare())return;
  let url='',anchor=null;
  try{
    url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
    anchor=document.createElement('a');anchor.href=url;anchor.download=filename;
    document.body.appendChild(anchor);
    if(owner!==currentProtectedOwner()||generation!==protectedFleetGeneration||mode!==fleetMode||(protectedOnly?!allowProtectedShare():!allowDashboardShare()))return;
    anchor.click();
    const downloadUrl=url;
    dashboardDownloadUrls.set(downloadUrl,setTimeout(()=>{URL.revokeObjectURL(downloadUrl);dashboardDownloadUrls.delete(downloadUrl)},15000));
    url='';
    toast('Download requested — check your browser downloads');
  }catch(error){toast('Download unavailable — refresh and try again')}
  finally{anchor?.remove();if(url)URL.revokeObjectURL(url)}
}
