function reconcileProtectedOwner(expectedUserId){let currentUserId=currentProtectedOwner();if(currentUserId===expectedUserId)return false;if(!currentUserId){resetProtectedFleet();return true}cancelProtectedFleetRefresh();clearProtectedFleetCache();protectedUserId=currentUserId;fleetMode=true;protectedAccountRefreshPending=true;showSignedOutActions(false);syncProtectedControls();document.getElementById('cloudStatus').textContent='Signed-in account changed. Loading the new account’s protected fleet data.';render();return true}
function recordProtectedRefreshFailure(stage){protectedRefreshFailures=Math.min(4,protectedRefreshFailures+1);let last=protectedLastSuccessfulAt?new Date(protectedLastSuccessfulAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'';document.getElementById('cloudStatus').textContent=stage==='account'?'Account check unavailable or timed out. Sign-out was not confirmed. '+(last?'Showing the protected data last updated at '+last+'. ':'Protected fleet data is unavailable. '):last?'Connection interrupted or timed out. Showing the protected data last updated at '+last+'. ':'Protected fleet data is temporarily unavailable or the request timed out. ';document.getElementById('cloudStatus').textContent+='Use Refresh now to retry; automatic retries will slow down to reduce data use.';refreshDashboardIfNeeded();window.OcculertPilotReport?.update()}
async function loadProtectedFleet(options={}){
  let includeEvents=options.includeEvents===true;
  if(protectedFleetLoading){if(includeEvents)protectedEventsRefreshPending=true;return false}
  setProtectedFleetBusy(true);
  let version=++protectedFleetGeneration,cancel,stage='account',backend=window.OcculertBackend,expectedUserId='';
  let cancelled=new Promise((_,reject)=>{cancel=()=>reject(new Error('Protected request superseded'))});cancelled.catch(()=>{});protectedFleetCancel=cancel;
  try{
    if(!backend?.currentUser)throw new Error('Protected backend unavailable');
    expectedUserId=currentProtectedOwner();
    if(!expectedUserId){resetProtectedFleet();return false}
    if(protectedUserId!==expectedUserId){clearProtectedFleetCache();protectedUserId=expectedUserId;fleetMode=true;render()}
    showSignedOutActions(false);fleetMode=true;syncProtectedControls();
    if(!backend.getSession||!backend.getFleetSummary)throw new Error('Protected backend unavailable');
    let session=await boundedProtectedFleetRequest(()=>backend.getSession(),cancelled);
    if(version!==protectedFleetGeneration)return false;
    if(reconcileProtectedOwner(expectedUserId))return false;
    if(session?.user?.id!==expectedUserId)throw new Error('Protected account could not be confirmed');
    stage='summary';
    let result=await boundedProtectedFleetRequest(()=>backend.getFleetSummary({includeEvents}),cancelled);
    if(version!==protectedFleetGeneration)return false;
    if(reconcileProtectedOwner(expectedUserId))return false;
    if(!result.ok&&result.status===401){backend.signOut();resetProtectedFleet();return false}
    if(result.ok){protectedReportShape=Array.isArray(result.body.sessions)&&Array.isArray(result.body.drivers);protectedTelemetryTrust=String(result.body.telemetry_trust||'');protectedReportPrivacy=result.body.privacy||null;window.OcculertFollowups?.show();protectedFleetId=String(result.body.fleet.id||'');restoreDashboardPreferences();protectedFleetName=result.body.fleet.company_name||'your fleet';protectedFleetPlan=String(result.body.fleet.plan||'fleet').slice(0,40);protectedDrivers=Array.isArray(result.body.drivers)?result.body.drivers:[];protectedSessions=Array.isArray(result.body.sessions)?result.body.sessions:[];if(result.body.events_included!==false){protectedEvents=Array.isArray(result.body.events)?result.body.events:[];protectedEventsLoadedAt=Date.now()}cloudRows=rowsFromFleet(result.body);protectedLastSuccessfulAt=Date.now();protectedRefreshFailures=0;sessionHistoryDirty=true;document.getElementById('cloudStatus').textContent='Protected connection active for '+protectedFleetName+'. Active sessions refresh every 30 seconds; otherwise the dashboard uses a lower-cost 90-second refresh.'}
    else if(result.body&&result.body.error==='fleet_not_found'){clearProtectedFleetCache();document.getElementById('cloudStatus').textContent='No owned fleet found. Use Fleet setup to create one and invite drivers.'}
    else{recordProtectedRefreshFailure(stage);return false}
    refreshDashboardIfNeeded();window.OcculertPilotReport?.update();return result.ok
  }catch(error){if(version!==protectedFleetGeneration)return false;if(backend?.currentUser&&reconcileProtectedOwner(expectedUserId))return false;recordProtectedRefreshFailure(stage);return false}
  finally{let refreshEvents=protectedEventsRefreshPending,refreshAccount=protectedAccountRefreshPending;protectedEventsRefreshPending=false;protectedAccountRefreshPending=false;if(protectedFleetCancel===cancel)protectedFleetCancel=null;setProtectedFleetBusy(false);if((refreshAccount||refreshEvents&&protectedRefreshFailures===0)&&fleetMode&&!document.hidden)void refreshProtectedFleetNow({forceEvents:refreshEvents})}
}
