/* fleet-refresh-scheduling:start */
function stopRefreshTimers(){clearInterval(dashboardRefreshTimer);clearTimeout(protectedRefreshTimer);dashboardRefreshTimer=0;protectedRefreshTimer=0}
function startDashboardClock(){clearInterval(dashboardRefreshTimer);dashboardRefreshTimer=0;if(!document.hidden)dashboardRefreshTimer=setInterval(refreshDashboardIfNeeded,DASHBOARD_CLOCK_INTERVAL_MS)}
function scheduleProtectedRefresh(){clearTimeout(protectedRefreshTimer);protectedRefreshTimer=0;if(document.hidden||!fleetMode)return;let hasActiveSession=cloudRows.some(row=>row.sessionActive),saveData=!hasActiveSession&&navigator.connection?.saveData===true,delay=protectedRefreshDelay({hasActiveSession,failureCount:protectedRefreshFailures,saveData});protectedRefreshTimer=setTimeout(()=>{void pollProtectedFleet()},delay)}
async function pollProtectedFleet(){if(document.hidden||!fleetMode)return;let includeEvents=shouldRefreshProtectedEvents({historyOpen:protectedHistoryOpen(),lastLoadedAt:protectedEventsLoadedAt});await loadProtectedFleet({includeEvents});scheduleProtectedRefresh()}
function startRefreshTimers(){stopRefreshTimers();if(document.hidden)return;startDashboardClock();scheduleProtectedRefresh()}
async function refreshProtectedFleetNow(options={}){clearTimeout(protectedRefreshTimer);protectedRefreshTimer=0;let includeEvents=shouldRefreshProtectedEvents({historyOpen:protectedHistoryOpen(),lastLoadedAt:protectedEventsLoadedAt,force:options.forceEvents===true});await loadProtectedFleet({includeEvents});scheduleProtectedRefresh()}
async function handleVisibilityChange(){if(document.hidden){stopRefreshTimers();return}startDashboardClock();refreshDashboardIfNeeded();if(fleetMode)await refreshProtectedFleetNow();else scheduleProtectedRefresh()}
/* fleet-refresh-scheduling:end */
async function handleAuthStorageChange(event){if(event.key!==null&&event.key!=='occulert-auth')return;let backend=window.OcculertBackend,currentUser=backend&&backend.currentUser?backend.currentUser():null,currentUserId=typeof currentUser?.id==='string'?currentUser.id:'';if(currentUserId===protectedUserId){if(!currentUserId)return;cancelProtectedFleetRefresh();if(protectedFleetLoading){protectedAccountRefreshPending=true;return}await refreshProtectedFleetNow();return}if(!currentUserId){resetProtectedFleet();startRefreshTimers();return}cancelProtectedFleetRefresh();clearProtectedFleetCache();protectedUserId=currentUserId;fleetMode=true;showSignedOutActions(false);syncProtectedControls();document.getElementById('cloudStatus').textContent='Signed-in account changed. Loading the new account’s protected fleet data.';render();if(protectedFleetLoading){protectedAccountRefreshPending=true;return}await refreshProtectedFleetNow()}
async function boot(){render();await new Promise(resolve=>setTimeout(resolve,100));await loadProtectedFleet();startRefreshTimers()}
document.addEventListener('visibilitychange',()=>{void handleVisibilityChange()});
window.addEventListener('storage',event=>{void handleAuthStorageChange(event)});
for(const id of ['riskFilter','sortMode'])document.getElementById(id)?.addEventListener('change',saveDashboardPreferences);
void boot();
